// utils/autoRefresh.js
/**
 * 自动整页刷新的「可见化 + 现场保全」（禅道 bug 6285 二次修复）。
 *
 * 原则：刷新只应因「确实检测到新版本 / 确实加载不到旧资源」而发生，
 * 绝不能因为用户点了一次菜单、跳转了一次路由而发生。
 * 版本检测由 version-check.js 用自己的定时器独立轮询，这里只负责刷新瞬间：
 * 1. 刷新前显示全屏遮罩提示（不再无声白屏）；
 * 2. 刷新前把已打开的页签写入 sessionStorage，刷新后由 TagsView 还原；
 * 3. 记录本次跳转目标，chunk 兜底刷新时把用户送回原本要去的页面。
 */

/** 自动刷新前保存页签用的会话级 key */
export const AUTO_REFRESH_VIEWS_KEY = 'auto-refresh-visited-views'
/** 刷新遮罩 DOM id */
const OVERLAY_ID = 'auto-refresh-overlay'

/** 当前正在进行的导航目标（fullPath），由 router 守卫写入 */
let pendingNavigationPath = ''
/** 最近一次路由跳转的时间戳：版本轮询据此避开跳转瞬间 */
let lastNavigationAt = 0

/** 记录本次跳转目标，供 chunk 兜底刷新后落到原目标页 */
export function setPendingNavigation(fullPath) {
  pendingNavigationPath = fullPath || ''
}

export function getPendingNavigation() {
  return pendingNavigationPath
}

export function clearPendingNavigation() {
  pendingNavigationPath = ''
}

/** 标记「刚刚发生过一次路由跳转」，用于让发版刷新避开用户操作 */
export function markNavigation() {
  lastNavigationAt = Date.now()
}

/** 指定时间窗口内是否仍在跳转（含未正常结束的跳转，靠时间戳自然过期） */
export function isNavigationRecentlyActive(withinMs = 800) {
  return Date.now() - lastNavigationAt < withinMs
}

/**
 * 整页刷新前显示全屏遮罩提示。
 * @param {string} message 提示文案
 */
export function showRefreshOverlay(message = '页面已更新，正在刷新…') {
  try {
    if (document.getElementById(OVERLAY_ID)) return
    const mask = document.createElement('div')
    mask.id = OVERLAY_ID
    Object.assign(mask.style, {
      position: 'fixed',
      left: '0',
      top: '0',
      right: '0',
      bottom: '0',
      zIndex: '99999',
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'center',
      background: 'rgba(255, 255, 255, 0.92)',
      color: '#303133',
      fontSize: '14px',
      lineHeight: '1.8',
      textAlign: 'center',
      whiteSpace: 'pre-wrap'
    })
    const box = document.createElement('div')
    box.textContent = message
    mask.appendChild(box)
    document.body.appendChild(mask)
  } catch (e) {
    // 遮罩失败不影响刷新流程
  }
}

/** 移除刷新遮罩（刷新失败或取消时兜底） */
export function hideRefreshOverlay() {
  try {
    const el = document.getElementById(OVERLAY_ID)
    if (el && el.parentNode) el.parentNode.removeChild(el)
  } catch (e) {
    // ignore
  }
}

/** 自动刷新前保存当前已打开的页签（供刷新后还原） */
export function saveRefreshVisitedViews() {
  try {
    const store = window.__VUE_APP_STORE__
    const views = (store && store.state && store.state.tagsView && store.state.tagsView.visitedViews) || []
    if (!views.length) return
    // meta 只保留可序列化的展示字段：route.meta 可能带组件/函数甚至循环引用，
    // 整对象 JSON.stringify 会抛错导致「一个页签都没存下来」（禅道 6285 页签 10→1）
    const payload = views.map((view) => ({
      path: view.path,
      fullPath: view.fullPath || view.path,
      name: view.name,
      query: view.query || {},
      params: view.params || {},
      meta: {
        title: view.meta && view.meta.title,
        icon: view.meta && view.meta.icon,
        affix: view.meta && view.meta.affix,
        noCache: view.meta && view.meta.noCache
      }
    }))
    sessionStorage.setItem(AUTO_REFRESH_VIEWS_KEY, JSON.stringify(payload))
  } catch (e) {
    // ignore
  }
}

/** 读取并清除自动刷新前保存的页签 */
export function consumeRefreshVisitedViews() {
  try {
    const raw = sessionStorage.getItem(AUTO_REFRESH_VIEWS_KEY)
    if (!raw) return []
    sessionStorage.removeItem(AUTO_REFRESH_VIEWS_KEY)
    const list = JSON.parse(raw)
    return Array.isArray(list) ? list : []
  } catch (e) {
    return []
  }
}

/**
 * 统一的「提示 → 刷新」动作：保留自动刷新语义，只是不再无声白屏。
 * @param {string} message 遮罩文案
 * @param {number} delay 延迟毫秒，让遮罩先渲染出来
 * @param {string} targetFullPath 本次跳转目标；chunk 兜底刷新发生在 pushHash 之前，
 *   不带目标会把用户退回旧页面（禅道 6285 复现根因），带上则刷新后落到原目标页
 */
export function reloadWithOverlay(message = '页面已更新，正在刷新…', delay = 600, targetFullPath = '') {
  saveRefreshVisitedViews()
  showRefreshOverlay(message)
  setTimeout(() => {
    if (targetFullPath) {
      try {
        const targetHash = `#${String(targetFullPath).replace(/^#/, '')}`
        if (window.location.hash !== targetHash) {
          window.location.hash = targetHash
        }
      } catch (e) {
        // 目标地址写入失败也要继续刷新，不能把用户卡在坏页面上
      }
    }
    window.location.reload()
  }, delay)
}

// utils/version-check.js
import { reloadWithOverlay, isNavigationRecentlyActive } from './autoRefresh'

class VersionChecker {
  constructor(options = {}) {
    this.versionUrl = options.versionUrl || `${import.meta.env.BASE_URL}version.json`
    // 版本检测走自己的定时器，与用户点击 / 路由跳转彻底解耦（禅道 bug 6285 二次修复）。
    // 下限 10s：避免高频轮询把一次正常点击误判成「该刷新了」。
    this.interval = Math.max(Number(options.interval) || 30000, 10000)
    this.currentVersion = null
    this.onUpdate = options.onUpdate || this.defaultUpdateHandler
    this.timer = null
    this.refreshScheduled = false
  }

  async init() {
    // 首次获取当前版本
    this.currentVersion = await this.fetchVersion()

    // 页面重新可见（切标签页回来）时立即检测一次，同样与用户点击无关
    document.addEventListener('visibilitychange', () => {
      if (document.visibilityState === 'visible') {
        this.checkUpdate()
      }
    })

    // 只在自己的节拍上检测。
    // 旧实现把 checkUpdate 挂在 pushState/replaceState/popstate/hashchange 上：
    // 任何一次路由跳转（如预售许可申请点「维护」）都会拉 version.json 比对，
    // 一旦发版后 buildTime 变化就 forceRefresh()，于是「点菜单」变成了「整页刷新」，
    // 表现为白屏一闪、页签全丢、跳转被中断（禅道 6285）。
    this.timer = window.setInterval(() => {
      this.checkUpdate()
    }, this.interval)
  }

  async fetchVersion() {
    try {
      // 加时间戳防止缓存
      const url = new URL(this.versionUrl, window.location.href)
      const res = await fetch(`${url.href}?t=${Date.now()}`, {
        cache: 'no-cache'
      })
      const data = await res.json()
      return data
    } catch (e) {
      console.error('获取版本信息失败:', e)
      return null
    }
  }

  async checkUpdate() {
    if (this.refreshScheduled) return
    const newVersion = await this.fetchVersion()
    if (!newVersion || !this.currentVersion) return

    // 对比版本号或构建时间
    if (newVersion.version !== this.currentVersion.version ||
        newVersion.buildTime !== this.currentVersion.buildTime) {
      // 先记下新版本，避免轮询与 visibilitychange 重复排队刷新
      this.currentVersion = newVersion
      this.refreshScheduled = true
      console.log('发现新版本:', newVersion)
      this.onUpdate(newVersion)
    }
  }

  defaultUpdateHandler() {
    this.forceRefresh()
  }

  forceRefresh() {
    // 清除缓存并刷新
    if ('caches' in window) {
      caches.keys().then((names) => {
        names.forEach((name) => caches.delete(name))
      })
    }
    // 保留「确实检测到新版本就自动整页刷新」语义；但仍避开正在进行的路由跳转，
    // 不把一次正常点击变成刷新现场（禅道 bug 6285）。
    const refreshWhenIdle = () => {
      if (isNavigationRecentlyActive(800)) {
        window.setTimeout(refreshWhenIdle, 200)
        return
      }
      reloadWithOverlay('检测到新版本，正在刷新页面…')
    }
    refreshWhenIdle()
  }

  destroy() {
    if (this.timer) {
      window.clearInterval(this.timer)
      this.timer = null
    }
  }
}

export default VersionChecker

