 */
restoreVisitedViewsAfterRefresh() {
  const saved = consumeRefreshVisitedViews()
  if (!saved.length) return
  const restore = () => {
    saved.forEach((view) => {
      if (!view.path) return
      this.$store.dispatch('tagsView/addVisitedView', {
        path: view.path,
        fullPath: view.fullPath || view.path,
        name: view.name,
        query: view.query || {},
        params: view.params || {},
        meta: view.meta || {}
      })
    })
  }
  if (this.$router && typeof this.$router.onReady === 'function') {
    this.$router.onReady(restore)
  } else {
    restore()
  }
},

