/** 部署后旧 HTML 引用的 chunk 404/502 时，自动刷新一次拉取最新资源 */
function importWithChunkRetry(importer) {
  return importer().then((module) => {
    // 加载成功即清除「本会话已因 chunk 失败刷新过」标记。
    // 旧实现只在再次失败时清除，刷新成功后标记残留一整个会话，
    // 后续真实发版再也无法自动恢复（禅道 6285 二次修复）。
    sessionStorage.removeItem(CHUNK_RELOAD_KEY)
    return module
  }).catch((err) => {
    const msg = String(err?.message || err || '')
    const isChunkLoadError =
      (err?.name === 'TypeError' || err?.name === 'ChunkLoadError') &&
      (/Failed to fetch dynamically imported module/i.test(msg) ||
        /Importing a module script failed/i.test(msg) ||
        /error loading dynamically imported module/i.test(msg) ||
        /Loading chunk [\d]+ failed/i.test(msg))
    if (isChunkLoadError && !sessionStorage.getItem(CHUNK_RELOAD_KEY)) {
      sessionStorage.setItem(CHUNK_RELOAD_KEY, '1')
      // 带上本次跳转目标：刷新发生在 pushHash 之前，不带目标会退回旧页面，
