import { chromium } from '@playwright/test'
import fs from 'node:fs'

const BASE = 'http://127.0.0.1:8098/'
const VERSION_FILE = 'D:/repository/szfc-v3-wt-bug-6285/dist/version.json'
const results = []
const consoleErrors = []

const browser = await chromium.launch({ headless: true })
const page = await browser.newPage()
page.on('pageerror', (e) => consoleErrors.push(String(e)))

try {
  await page.goto(BASE, { waitUntil: 'load', timeout: 30000 })
  // main.js 同步执行完即挂上 __VUE_APP_STORE__，用它确认应用入口已加载
  await page.waitForFunction(() => typeof window.__VUE_APP_STORE__ !== 'undefined', null, { timeout: 20000 })

  // 断言 1：旧实现的 history.pushState 覆写已移除
  const isNative = await page.evaluate(() => history.pushState.toString().includes('[native code]'))
  results.push(['history.pushState 保持原生（版本检测不再挂钩路由跳转）', isNative])

  // 断言 2：模拟一次路由跳转，2.5s 内不应因跳转发出任何 version.json 请求
  // （轮询间隔 30s，正常不会在这个窗口触发；旧实现会立即触发）
  let navTriggeredFetch = false
  const waitFetch = page.waitForResponse(
    (r) => r.url().includes('version.json'),
    { timeout: 2500 }
  ).then(() => { navTriggeredFetch = true }).catch(() => {})
  await page.evaluate(() => {
    history.pushState({}, '', '#/smoke-nav-1')
    history.pushState({}, '', '#/smoke-nav-2')
    history.replaceState({}, '', '#/smoke-nav-3')
    window.dispatchEvent(new PopStateEvent('popstate'))
    window.dispatchEvent(new HashChangeEvent('hashchange'))
  })
  await waitFetch
  results.push(['点菜单/路由跳转不再触发 version.json 比对', !navTriggeredFetch])

  // 断言 3：真的发版（version.json 变化）时，自动刷新仍然存在且给出可见遮罩
  const original = fs.readFileSync(VERSION_FILE, 'utf8')
  const bumped = original.replace(/"buildTime":\s*"[^"]+"/, '"buildTime": "2026/11/9 12:59:00"')
  fs.writeFileSync(VERSION_FILE, bumped)
  let overlayText = ''
  try {
    const overlay = page.locator('#auto-refresh-overlay')
    await overlay.waitFor({ state: 'visible', timeout: 40000 })
    overlayText = (await overlay.textContent()) || ''
  } finally {
    fs.writeFileSync(VERSION_FILE, original)
  }
  results.push(['真实发版仍触发自动刷新并显示遮罩', overlayText.includes('检测到新版本')])
} finally {
  await browser.close()
}

console.log('=== 6285 部署站点冒烟验证 ===')
for (const [name, ok] of results) console.log(`${ok ? 'PASS' : 'FAIL'}  ${name}`)
console.log(`pageerror 数量: ${consoleErrors.length}`)
if (consoleErrors.length) console.log(consoleErrors.slice(0, 5).join('\n'))
const failed = results.filter(([, ok]) => !ok)
if (failed.length) process.exit(1)
